# group generated by the bottom flips f_A..f_D: restrict to the blocks of the model, test short relations
import numpy as np, itertools, sys
f=np.load('wreathcoords_f.npy'); v=np.load('wreathcoords_v.npy')
# block decomposition of the full model algebra via random element of commutant (from v and f? use P directly)
sys.path.insert(0,'/home/claude/dita'); sys.path.insert(0,'/home/claude/jw/jw')
import matrices as Mx
from magic import magic
rng=np.random.default_rng(7); a,b,c,d,e=[np.exp(2j*np.pi*rng.random()) for _ in range(5)]
P=magic(Mx.F85a(a,b,c,d,e))
gens=[P[i,j] for i in range(8) for j in range(8)]
B=np.eye(64,dtype=complex)
for Q in gens:
    M=np.array([(Q@B[:,t].reshape(8,8)-B[:,t].reshape(8,8)@Q).ravel() for t in range(B.shape[1])]).T
    u,s,vh=np.linalg.svd(M,full_matrices=False); r=(s>1e-8).sum(); B=B@vh[r:].conj().T
X=sum(rng.standard_normal()*B[:,t].reshape(8,8) for t in range(B.shape[1])); X=X+X.conj().T
w,V=np.linalg.eigh(X)
grp=[];
for i,x in enumerate(w):
    if grp and abs(x-w[grp[-1][0]])<1e-6: grp[-1].append(i)
    else: grp.append([i])
for g in grp:
    Vb=V[:,g]; fb=[Vb.conj().T@x@Vb for x in f]; n=len(g)
    print("block dim",n)
    if n==1: print("  f values:",[round(x[0,0].real,6) for x in fb]); continue
    tr=[[np.round(np.trace(fb[i]@fb[j]),5) for j in range(4)] for i in range(4)]
    print("  tr(f_i f_j):",tr)
    print("  [f_if_j, f_kf_l] commute?",[ (i,j,k,l) for (i,j) in itertools.combinations(range(4),2) for (k,l) in itertools.combinations(range(4),2) if (i,j)<(k,l) and np.allclose(fb[i]@fb[j]@fb[k]@fb[l],fb[k]@fb[l]@fb[i]@fb[j])])
    # short relations: reduced words in 4 involutions up to length Lmax equal to scalar
    Lmax=10 if n==2 else 12
    found=[]
    frontier=[((),np.eye(n))]
    for L in range(1,Lmax+1):
        new=[]
        for word,Mw in frontier:
            for s in range(4):
                if word and word[-1]==s: continue
                M2=Mw@fb[s]; w2=word+(s,)
                if np.allclose(M2, M2[0,0]*np.eye(n),atol=1e-8): found.append(w2)
                new.append((w2,M2))
        frontier=new
    print("  words up to length",Lmax,"acting as scalars:",len(found), found[:6])
